window.i18n = {
  currentLang: 'en',
  dictionary: DICTIONARY,
  supportedLangs: ['en', 'de', 'fr', 'es', 'it', 'pt', 'nl', 'th'],

  init() {
    let saved = null;
    try {
      saved = localStorage.getItem('poli_tools_language');
    } catch (e) {
      // localStorage may be restricted in sandbox iframe
    }
    if (saved && this.supportedLangs.includes(saved)) {
      this.currentLang = saved;
    } else {
      this.currentLang = 'en';
    }
  },

  setLanguage(lang) {
    if (!this.supportedLangs.includes(lang)) return;
    this.currentLang = lang;
    try {
      localStorage.setItem('poli_tools_language', lang);
    } catch (e) {
      // ignore
    }
  },

  t(key, params) {
    const langDict = this.dictionary[this.currentLang] || this.dictionary['en'];
    let text = langDict ? langDict[key] : undefined;
    if (text === undefined && this.dictionary['en']) {
      text = this.dictionary['en'][key];
    }
    if (text === undefined) {
      return key;
    }
    if (params && typeof params === 'object') {
      for (const p in params) {
        text = text.replaceAll('{' + p + '}', params[p]);
      }
    }
    return text;
  },

  getAllKeys(lang = 'en') {
    return Object.keys(this.dictionary[lang] || {});
  }
};

window.i18n.init();
